// ▼ 여기만 수정하세요 ▼
return [{
  json: {
    githubOwner: 'YOUR_GITHUB_ID',
    githubRepo: 'ai-news-site',
    githubBranch: 'main',
    siteUrl: 'https://your-site.vercel.app',
    geminiModel: 'gemini-2.5-flash',
    discordWebhookUrl: 'https://discord.com/api/webhooks/XXXX/YYYY',
    maxItemsForGemini: 90,   // Gemini에 넘길 최대 기사 수
    maxPerSource: 10,        // 매체당 최대 기사 수 (한 매체 쏠림 방지)
  },
}];

// trust: 매체 기본 신뢰도(1~5). hn: 해커뉴스(포인트 기반 인기 신호)
// URL은 매체 사정으로 바뀔 수 있으니 첫 실행 때 RSS 노드 결과를 확인하세요.
const feeds = [
  // ── AI ──
  { category: 'ai', source: 'OpenAI', url: 'https://openai.com/news/rss.xml', trust: 5 },
  { category: 'ai', source: 'Google AI Blog', url: 'https://blog.google/technology/ai/rss/', trust: 5 },
  { category: 'ai', source: 'Google DeepMind', url: 'https://deepmind.google/blog/rss.xml', trust: 5 },
  { category: 'ai', source: 'Hugging Face', url: 'https://huggingface.co/blog/feed.xml', trust: 4 },
  { category: 'ai', source: 'MIT Technology Review', url: 'https://www.technologyreview.com/topic/artificial-intelligence/feed', trust: 5 },
  { category: 'ai', source: 'TechCrunch', url: 'https://techcrunch.com/category/artificial-intelligence/feed/', trust: 4 },
  { category: 'ai', source: 'The Verge', url: 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml', trust: 4 },
  { category: 'ai', source: 'VentureBeat', url: 'https://venturebeat.com/category/ai/feed/', trust: 4 },
  { category: 'ai', source: 'AI타임스', url: 'https://www.aitimes.com/rss/allArticle.xml', trust: 3 },
  { category: 'ai', source: 'Hacker News', url: 'https://hnrss.org/newest?q=AI+OR+LLM+OR+GPT&points=100', trust: 3, hn: true },
  // ── 국제 ──
  { category: 'world', source: 'BBC News', url: 'https://feeds.bbci.co.uk/news/world/rss.xml', trust: 5 },
  { category: 'world', source: 'NPR', url: 'https://feeds.npr.org/1004/rss.xml', trust: 5 },
  { category: 'world', source: 'The Guardian', url: 'https://www.theguardian.com/world/rss', trust: 4 },
  { category: 'world', source: 'Al Jazeera', url: 'https://www.aljazeera.com/xml/rss/all.xml', trust: 4 },
  { category: 'world', source: '연합뉴스', url: 'https://www.yna.co.kr/rss/international.xml', trust: 4 },
];
return feeds.map((f, i) => ({ json: { ...f, feedIndex: i } }));

// RSS 결과 정리 → 기간 필터 → 중복 제거 → Gemini 요청 생성
const cfg = $('설정').first().json;
const feeds = $('RSS 피드 목록').all().map((i) => i.json);
const now = Date.now();
const DAY = 864e5;
const windowDays = { ai: 7, world: 3 };

const host = (u) => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch { return ''; } };
const clean = (s = '') => String(s).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

const seen = new Set();
const perSource = {};
const articles = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.link || !r.title) continue;               // 실패한 피드는 건너뜀
  const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const feed = feeds[p?.item] ?? feeds.find((f) => host(r.link) && f.url.includes(host(r.link))) ?? { category: 'ai', source: host(r.link), trust: 2 };

  const published = new Date(r.isoDate || r.pubDate || now);
  if (isNaN(published)) continue;
  if (now - published.getTime() > windowDays[feed.category] * DAY) continue;

  let url = r.link;
  try { const u = new URL(r.link); u.hash = ''; [...u.searchParams.keys()].filter((k) => k.startsWith('utm_')).forEach((k) => u.searchParams.delete(k)); url = u.toString(); } catch {}
  const key = url.toLowerCase().replace(/\/$/, '');
  if (seen.has(key)) continue;
  seen.add(key);

  perSource[feed.source] = (perSource[feed.source] ?? 0) + 1;
  if (perSource[feed.source] > cfg.maxPerSource) continue;

  const hnPoints = feed.hn ? Number((clean(r.content || r.contentSnippet).match(/Points:\s*(\d+)/) || [])[1] || 0) : 0;

  articles.push({
    category: feed.category,
    source: feed.source,
    trust: feed.trust,
    hnPoints,
    title: clean(r.title),
    url,
    publishedAt: published.toISOString(),
    snippet: clean(r.contentSnippet || r.content || r.summary).slice(0, 450),
  });
}

// 최신순 정렬 후 개수 제한
articles.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
const picked = articles.slice(0, cfg.maxItemsForGemini).map((a, id) => ({ id, ...a }));

if (picked.length === 0) throw new Error('수집된 기사가 없습니다. RSS 피드 URL을 확인하세요.');

const prompt = `당신은 한국어 뉴스 브리핑 편집자입니다. 아래 기사 목록(JSON)을 검토해 결과를 JSON으로만 답하세요.

각 기사(id 기준)에 대해:
- keep: AI 카테고리에서 AI와 무관하거나, 광고·보도자료 홍보성·단순 목록 글이면 false. 국제 카테고리에서 연예·스포츠 단신이면 false.
- titleKo: 자연스러운 한국어 제목 (원문이 한국어면 그대로)
- summary: 사실만으로 2~3문장 한국어 요약. 제공된 내용에 없는 사실을 지어내지 말 것.
- keyPoints: 핵심 2~3개 (각 40자 이내)
- tags: 한국어 태그 2~4개 (예: LLM, 오픈소스, 규제, 반도체, 투자, 에이전트, 연구, 외교, 경제)
- credibility: 1~5. 공식 발표·1차 출처·주요 통신사=5, 주요 언론=4, 전문 블로그·커뮤니티=3, 근거 부족·추측=1~2
- impact: 0~100. 업계·사회에 미치는 영향과 화제성
- storyKey: 같은 사건을 다룬 기사끼리 같은 값 (영문 소문자-하이픈, 예: "eu-ai-act-guidance")

그리고 briefing: AI 카테고리의 오늘 핵심 흐름 3~4개를 마크다운 글머리표로 작성 ("- **키워드**: 한 문장").

기사 목록:
${JSON.stringify(picked.map(({ id, category, source, title, publishedAt, snippet }) => ({ id, category, source, title, publishedAt, snippet })))}`;

const geminiRequest = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: 32768,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        briefing: { type: 'STRING' },
        items: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              id: { type: 'INTEGER' },
              keep: { type: 'BOOLEAN' },
              titleKo: { type: 'STRING' },
              summary: { type: 'STRING' },
              keyPoints: { type: 'ARRAY', items: { type: 'STRING' } },
              tags: { type: 'ARRAY', items: { type: 'STRING' } },
              credibility: { type: 'INTEGER' },
              impact: { type: 'INTEGER' },
              storyKey: { type: 'STRING' },
            },
            required: ['id', 'keep', 'titleKo', 'summary', 'keyPoints', 'tags', 'credibility', 'impact', 'storyKey'],
          },
        },
      },
      required: ['briefing', 'items'],
    },
  },
};

return [{ json: { articles: picked, geminiRequest } }];

// Gemini 결과 병합 → 인기도 계산 → Markdown 다이제스트 + Discord 메시지 생성
const cfg = $('설정').first().json;
const { articles } = $('기사 정리 & 프롬프트').first().json;

const text = $json.candidates?.[0]?.content?.parts?.map((p) => p.text ?? '').join('') ?? '';
let result;
try { result = JSON.parse(text.replace(/```json|```/g, '').trim()); }
catch (e) { throw new Error('Gemini 응답을 JSON으로 읽지 못했습니다: ' + text.slice(0, 300)); }

const ai = new Map(result.items.map((r) => [r.id, r]));
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
const now = Date.now();

// 1) 병합
let merged = articles
  .map((a) => ({ a, r: ai.get(a.id) }))
  .filter(({ r }) => r && r.keep);

// 2) 같은 사건(storyKey) 묶기 → 보도 매체 수(coverage)
const groups = new Map();
for (const m of merged) {
  const k = `${m.a.category}:${m.r.storyKey || m.a.url}`;
  groups.set(k, [...(groups.get(k) ?? []), m]);
}

const items = [];
for (const group of groups.values()) {
  // 대표 기사: 매체 신뢰도 높은 순 → 먼저 보도한 순
  group.sort((x, y) => y.a.trust - x.a.trust || x.a.publishedAt.localeCompare(y.a.publishedAt));
  const { a, r } = group[0];
  const coverage = new Set(group.map((g) => g.a.source)).size;
  const hn = Math.max(...group.map((g) => g.a.hnPoints || 0));
  const ageH = (now - Date.parse(a.publishedAt)) / 36e5;

  // 인기도 = Gemini 영향도 60% + 보도 매체 수 + HN 포인트 + 최신성
  const hotScore = clamp(Math.round(
    r.impact * 0.6 +
    Math.min(coverage - 1, 4) * 6 +
    Math.min(hn / 30, 10) +
    (ageH < 24 ? 8 : ageH < 48 ? 4 : 0)
  ), 0, 100);

  items.push({
    category: a.category,
    title: a.title,
    titleKo: r.titleKo,
    source: a.source,
    url: a.url,
    publishedAt: a.publishedAt,
    summary: r.summary,
    keyPoints: (r.keyPoints || []).slice(0, 3),
    tags: (r.tags || []).slice(0, 4),
    credibility: clamp(Math.round((r.credibility + a.trust) / 2), 1, 5), // AI 판단 + 매체 기본값
    hotScore,
    coverage,
  });
}
items.sort((x, y) => y.publishedAt.localeCompare(x.publishedAt));

// 3) Markdown (frontmatter의 각 항목은 JSON — YAML에서 그대로 읽힘)
const kst = new Date(now + 9 * 36e5);
const date = kst.toISOString().slice(0, 10);
const generatedAt = kst.toISOString().slice(0, 19) + '+09:00';
const md = [
  '---',
  `date: "${date}"`,
  `generatedAt: "${generatedAt}"`,
  'items:',
  ...items.map((i) => '  - ' + JSON.stringify(i)),
  '---',
  '',
  result.briefing.trim(),
  '',
].join('\n');

// 4) Discord 메시지
const top = (cat, n) => items.filter((i) => i.category === cat).sort((x, y) => y.hotScore - x.hotScore).slice(0, n);
const line = (i, k) => `**${k + 1}. [${i.titleKo}](${i.url})**\n${i.source} · 인기도 ${i.hotScore}`;
const discord = {
  username: 'AI 뉴스 브리프',
  embeds: [
    { title: `📰 ${date} AI 뉴스 브리핑`, url: cfg.siteUrl, description: result.briefing.slice(0, 1500), color: 0x2b4acb },
    { title: '🔥 AI Hot News', url: `${cfg.siteUrl}/hot`, description: top('ai', 5).map(line).join('\n\n').slice(0, 4000), color: 0xc9430e },
    { title: '🌍 국제 Hot News', url: `${cfg.siteUrl}/world`, description: top('world', 3).map(line).join('\n\n').slice(0, 4000) || '수집된 기사 없음', color: 0x0b7470 },
  ],
};

return [{
  json: {
    path: `src/content/news/${date}.md`,
    contentBase64: Buffer.from(md, 'utf8').toString('base64'),
    commitMessage: `news: ${date} 다이제스트 (${items.length}건)`,
    discord,
    count: items.length,
  },
}];
